import sys

def fact_tail(n, acc=1):
    if n == 0:
        return acc
    return fact_tail(n - 1, acc * n)

def solve():
    data = sys.stdin.read().split()
    out_lines = []
    for token in data:
        try:
            n = int(token)
        except ValueError:
            continue
        if n < 0:
            out_lines.append("-1")
        else:
            out_lines.append(str(fact_tail(n)))
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
